package com.vandorlabs.neoforge;
import com.google.gson.*;
import com.vandorlabs.render.ScreenSurface;
import com.vandorlabs.screen.*;
import com.vandorlabs.neoforge.screen.NativeScreenRenderProjection;
import com.vandorlabs.neoforge.screen.NativeScreenCatalog;
import org.joml.Matrix4f;
/** CPU affine proof uses real whole-TESR font matrices; group/world preparation is a separate check. */
public final class NativeScreenJoinedJournalChecks {
 public static void main(String[] args)throws Exception{
  int profiles=0,commands=0,negative=0;double error=0,contentError=0;var pose=new double[16];var nativePose=new float[16];var ui=new Matrix4f();var matrix=new Matrix4f();
  var entry=ModernFinishCatalog.option(NativeScreenCatalog.INSTANCE.sourceChoice("frames/frames-door-window/lights-cyan-1"));var texture=net.minecraft.resources.ResourceLocation.parse(entry.texture());NativeTrapdoorFrameBorders.Borders border;try(var stream=NativeScreenJoinedJournalChecks.class.getResourceAsStream("/assets/"+texture.getNamespace()+"/textures/"+texture.getPath()+".png")){if(stream==null)throw new AssertionError("Generated frame resource missing "+texture);border=NativeTrapdoorFrameBorders.read(javax.imageio.ImageIO.read(stream),entry.frame().aspect());}
  try(var input=new java.util.zip.GZIPInputStream(new java.io.FileInputStream(System.getProperty("screenJoinedJournalReference")));var lines=new java.io.BufferedReader(new java.io.InputStreamReader(input,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=lines.readLine())!=null){var row=JsonParser.parseString(line).getAsJsonObject();int facing=row.get("facing").getAsInt(),columns=row.get("columns").getAsInt(),rows=row.get("rows").getAsInt();if(row.get("submissions").getAsInt()!=1||row.get("ownerColumn").getAsInt()!=(facing==1?columns-1:0)||row.get("ownerRow").getAsInt()!=(facing==0?rows-1:0))throw new AssertionError("Source six-face owner orientation "+facing+" "+columns+"x"+rows);
   var source=row.getAsJsonArray("content");int frameMode=row.get("frame").getAsInt();var raw=new NativeScreenRenderProjection.Rectangle(row.get("ownerColumn").getAsInt(),row.get("ownerRow").getAsInt(),columns,rows);var partition=frameMode==2?NativeScreenRenderProjection.Rectangle.SINGLE:NativeScreenRenderProjection.frameRectangle(facing,true,raw);var content=content(frameMode,partition,border);if(NativeScreenRenderProjection.frameRectangle(facing,false,raw)!=raw)throw new AssertionError("Normal frames retain identity");if(frameMode==1&&(facing==1&&columns>1||facing==0&&rows>1)){var old=content(frameMode,NativeScreenRenderProjection.frameRectangle(facing,false,raw),border);if(Math.abs(old.topLeft.x-source.get(3).getAsDouble())<1e-12&&Math.abs(old.topRight.x-source.get(0).getAsDouble())<1e-12&&Math.abs(old.topRight.y-source.get(1).getAsDouble())<1e-12&&Math.abs(old.bottomRight.y-source.get(4).getAsDouble())<1e-12)throw new AssertionError("Old unmirrored vertical frame did not fail against actual Source");negative++;}double[] actual={content.topRight.x,content.topRight.y,content.topRight.z,content.topLeft.x,content.bottomRight.y,content.bottomRight.z,content.ny,content.nz};for(int i=0;i<8;i++)contentError=Math.max(contentError,Math.abs(actual[i]-source.get(i).getAsDouble()));
   int height=NativeScreenJournalRenderer.joinedHeight(content,columns,rows);var text=row.getAsJsonArray("text");for(int i=text.size()-3;i<text.size();i++)if(text.get(i).getAsJsonObject().get("y").getAsInt()!=height-16)throw new AssertionError("Actual Source footer-derived height "+facing+" "+columns+"x"+rows+" frame="+row.get("frame"));
   NativeScreenJournalRenderer.joinedUiMatrix(content,columns,rows,height,ui);ScreenRenderPose.write(ScreenFamily.SCREEN,new ScreenFamily.State(facing,false,false,false),false,1,pose);for(int i=0;i<16;i++)nativePose[i]=(float)pose[i];matrix.set(nativePose).mul(ui).translate(0,0,.04F); // Shared canvas glyph depth, independently frozen by the local journal oracle.
   for(var element:text){var command=element.getAsJsonObject();var expected=command.getAsJsonArray("matrix");if(expected.size()!=16)throw new AssertionError("Source font affine format");for(int c=0;c<4;c++)for(int r=0;r<4;r++){double delta=Math.abs(matrix.get(c,r)-Float.intBitsToFloat(expected.get(c*4+r).getAsInt()));error=Math.max(error,delta);if(delta>2e-6)throw new AssertionError("Actual whole font affine face="+facing+" rectangle="+columns+"x"+rows+" frame="+row.get("frame")+" command="+command.get("text")+" coordinate="+c+","+r+" expected="+Float.intBitsToFloat(expected.get(c*4+r).getAsInt())+" native="+matrix.get(c,r));}commands++;}profiles++;
  }}if(profiles!=144||commands!=864||negative!=10||contentError>1e-12)throw new AssertionError("Whole Source joined affine/content input coverage");System.out.println("Native joined journal affine PASS profiles="+profiles+" fontcommands="+commands+" maxMatrixError="+error+" generatedFrameContentError="+contentError+" oldUnmirroredNegative="+negative+" owner-only/all6facings");
 }
 private static ScreenSurface.Quad content(int mode,NativeScreenRenderProjection.Rectangle frame,NativeTrapdoorFrameBorders.Borders border){var full=ScreenSurface.quad(ScreenSurface.Kind.FLAT,false);if(mode==0)return full;return ScreenSurface.inset(full,frame.column()==0?border.left():0,frame.column()==frame.columns()-1?border.right():0,frame.row()==frame.rows()-1?border.top():0,frame.row()==0?border.bottom():0);}

}
